MappingFormula.PseudoCode:
swift_code = extract_from_field_61(transaction_type)
code_map = {
  "NMSC": { domain: "PMNT", family: "RCDT", subfamily: "ESCT" },
  "NTRF": { domain: "PMNT", family: "ICDT", subfamily: "DMCT" },
  "NDDT": { domain: "PMNT", family: "RDDT", subfamily: "ESDD" },
  "NCHK": { domain: "PMNT", family: "RCDT", subfamily: "CHQB" },
  "NCHG": { domain: "PMNT", family: "MCOP", subfamily: "CHRG" },
  "NSTO": { domain: "PMNT", family: "ICDT", subfamily: "STDO" },
  "NCMS": { domain: "CMDT", family: "CMDT", subfamily: "SWEP" }
}
if (code_map.contains(swift_code)) then
  mapping = code_map[swift_code]
  bank_tx_code = {
    Domain: { Code: mapping.domain, Family: { Code: mapping.family, SubFamilyCode: mapping.subfamily } }
  }
else
  log_warning("No ISO 20022 mapping for SWIFT code: " + swift_code)
  bank_tx_code = { Proprietary: { Code: swift_code, Issuer: "SWIFT" } }
endif
return bank_tx_code
